{"source":"def investigate(context, acquire):
    events = context.get('events')
    if events is None:
        events = []
    count = 0
    status = 'open'
    pending = []
    for event in events:
        op = event.get('op')
        if op == 'feed':
            if status == 'error' or status == 'finished':
                continue
            data = event.get('bytes')
            if data is None:
                data = []
            pending.extend(data)
            text = ''
            while len(pending) > 0:
                lead = pending[0]
                if lead < 128:
                    need = 0
                elif 192 <= lead <= 223:
                    need = 1
                elif 224 <= lead <= 239:
                    need = 2
                elif 240 <= lead <= 247:
                    need = 3
                else:
                    status = 'error'
                    pending = []
                    break
                if len(pending) < 1 + need:
                    break
                valid = True
                index = 1
                while index <= need:
                    trail = pending[index]
                    if trail < 128 or 191 < trail:
                        valid = False
                        break
                    if need == 2 and index == 1:
                        if lead == 224 and not (160 <= trail <= 191):
                            valid = False
                            break
                        if lead == 239 and not (128 <= trail <= 191):
                            valid = False
                            break
                    if need == 3 and index == 1:
                        if lead == 240 and not (144 <= trail <= 191):
                            valid = False
                            break
                        if lead == 244 and not (128 <= trail <= 143):
                            valid = False
                            break
                    index = index + 1
                if not valid:
                    status = 'error'
                    pending = []
                    break
                if need == 0:
                    low = 0
                    high = 127
                elif need == 1:
                    low = 128
                    high = 2047
                elif need == 2:
                    low = 2048
                    high = 65535
                else:
                    low = 65536
                    high = 1114111
                value = lead & (127 >> need)
                index = 1
                while index <= need:
                    value = (value << 6) | (pending[index] & 63)
                    index = index + 1
                if value < low or value > high or (55296 <= value <= 57343):
                    status = 'error'
                    pending = []
                    break
                text = text + chr(value)
                del pending[:1 + need]
            if status == 'error':
                continue
            count = count + len(text)
        elif op == 'finish':
            if status == 'error' or status == 'finished':
                continue
            if len(pending) > 0:
                status = 'error'
                pending = []
            else:
                status = 'finished'
        elif op == 'reset':
            count = 0
            status = 'open'
            pending = []
    return {'count': count, 'status': status}
","scope":"Strict incremental UTF-8 decoder over feed/finish/reset events. Enforces ASCII, continuation-byte, lead-length, overlong, surrogate, and U+10FFFF constraints; E0 requires A0-BF, ED requires 80-9F, F0 requires 90-BF, and F4 requires 80-8F second bytes. Counts code points only from successful non-final feeds; a failing feed contributes zero including its valid prefix; finish errors on any incomplete prefix.","change":"Removed the unsupported ''.join expression and accumulated decoded code points directly in text. Added strict second-byte range checks for E0/ED/F0/F4 so overlong, surrogate, and out-of-range sequences now produce error instead of being accepted by the parent's range-only validation."}
